*merge in filing status from audit analytics;
proc sql;
create table comprestate2 as
select a.*, b.pe_date, b.HST_IS_LARGE_ACCEL, b.HST_IS_ACCEL_FILER
from comprestate as a left join wrds.accfiler as b
on a.cik = b.company_fkey and intnx('day',b.pe_date,-15) <= a.datadate <= intnx('day',b.pe_date,15)
order by gvkey, datadate;
quit;
run;
proc sort data=comprestate2 nodupkey; by gvkey datadate;run;

