*merge in benfords;
*proprietary code to produce the "benfords" dataset generously provided by Dan Amiram;
*please refer to Amiram, D., Z. Bozanic, and E. Rouen. 2015. Financial statement errors: evidence from the distributional 
properties of financial statement numbers. Review of Accounting Studies 20(4): 1540–1593. for further details;
proc sql;
create table comprestatefsd as
select a.*, b.fsd
from comprestate2 as a left join benfords as b
on a.gvkey = b.gvkey and a.datadate = b.datadate

*merge in dgtw returns data;
*We obtained data on monthly return data calculated following the procedure in Daniel, Grinblatt, Titman and Wermers (1997) from Professor Mike Drake;
*if DGTW returns are missing, we replace missing "dgtw_bhar" values with buy and hold returns calculated as follows;
/*

**************merge in IO data;
*code obtained from WRDS website and run to produce the institown dataset merged in below;
*https://wrds-www.wharton.upenn.edu/pages/support/applications/institutional-ownership-research/institutional-ownership-concentration-and-breadth-ratios/;
proc sql; create table comprestatefsd as select
	a.*, ior as instit_own
	from comprestatefsd a left join institown b
	on a.datadate eq b.rdate and a.permno eq b.permno
	order by gvkey, datadate;

