*calculate share turnover and std of returns;
proc sql; create table compret as select
	a.gvkey, a.datadate, a.permno, b.ret, (b.vol*100)/(b.shrout*1000) as turnover, b.date 
	from controls_2001 as a left join wrds.msf as b
	on a.permno eq b.permno
	and intnx('month',a.datadate,-11) <= b.date <=intnx('month',a.datadate,1) 
	order by gvkey, datadate, date;
	quit;run;
